def all_subterms(value):
    out = []
    todo = [value]
    while todo:
        item = todo.pop()
        if isinstance(item, list) and item:
            out.append(item)
            i = 1
            while i < len(item):
                if isinstance(item[i], list):
                    todo.append(item[i])
                i += 1
    return out

def contains(value, name):
    for item in all_subterms(value):
        if item[0] == name:
            return True
    return False

def atoms_dec_subterms(value):
