                    todo.append(item[i])
                i+=1
    return out

def atoms_dec_has(value,name):
    for item in atoms_dec_subterms(value):
        if item[0]==name:
            return True
    return False

def atoms_dec_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
